{{!-- Styling parameters: class, titleClass, descriptionClass --}}
{{#with this as |ghostcnStyles|}}
<div class="ghcn-ui-alert{{#if ghostcnStyles.class}} {{ghostcnStyles.class}}{{/if}}" data-variant="{{#match variant "secondary"}}secondary{{else}}{{#match variant "outline"}}outline{{else}}{{#match variant "destructive"}}destructive{{else}}default{{/match}}{{/match}}{{/match}}" data-size="{{#match size "sm"}}sm{{else}}{{#match size "lg"}}lg{{else}}default{{/match}}{{/match}}" role="{{#if urgent}}alert{{else}}status{{/if}}">
  {{#if heading}}<h3 class="ghcn-ui-alert__title{{#if ghostcnStyles.titleClass}} {{ghostcnStyles.titleClass}}{{/if}}">{{heading}}</h3>{{/if}}
  <p class="ghcn-ui-alert__description{{#if ghostcnStyles.descriptionClass}} {{ghostcnStyles.descriptionClass}}{{/if}}">{{#if description}}{{description}}{{else}}An update for your readers.{{/if}}</p>
</div>
{{/with}}

.ghcn-ui-alert { box-sizing: border-box; font-family: inherit; font-size: var(--ghcn-text-body, 16px); line-height: 1.5; color: var(--foreground); }
.ghcn-ui-alert, .ghcn-ui-alert * { box-sizing: border-box; }
.ghcn-ui-alert:where([data-size="sm"]) { font-size: 14px; }
.ghcn-ui-alert:where([data-size="lg"]) { font-size: 18px; }
.ghcn-ui-alert:focus-visible, :where(.ghcn-ui-alert) :focus-visible { outline: 2px solid var(--ring, currentColor); outline-offset: 2px; }
.ghcn-ui-alert { box-sizing: border-box; min-width: 0; overflow-wrap: anywhere; border: 1px solid var(--border, #e4e4e7); border-radius: var(--ghcn-panel-radius, min(var(--radius, 8px), 24px)); background: var(--card, #fff); color: var(--card-foreground, #09090b); padding: 16px; }
.ghcn-ui-alert:where([data-size="sm"]) { padding: 12px; }
.ghcn-ui-alert:where([data-size="lg"]) { padding: var(--ghcn-panel-padding, clamp(16px, 3vw, 24px)); }
.ghcn-ui-alert:where([data-variant="secondary"]) { background: var(--secondary); color: var(--secondary-foreground); }
.ghcn-ui-alert:where([data-variant="outline"]) { background: transparent; }
.ghcn-ui-alert:where([data-variant="destructive"]) { border-color: var(--destructive); color: var(--destructive); }
.ghcn-ui-alert__title { font-size: 1em; margin: 0 0 .375em; font-weight: 600; }
.ghcn-ui-alert__description { margin: 0; }
